import numpy as np

def relu(x):
    return np.maximum(0, x)

def xavier_init(input_size, output_size, seed):
    limit = np.sqrt(6 / (input_size + output_size))
    return np.random.RandomState(seed).uniform(-limit, limit, size=(input_size, output_size))

def he_init(input_size, output_size, seed):
    std = np.sqrt(2 / input_size)
    return np.random.RandomState(seed).normal(scale=std, size=(input_size, output_size))

layer_sizes = [200, 200, 200, 200, 200]
x = np.random.RandomState(0).normal(size=(1, layer_sizes[0]))

print("Xavier Initialization with ReLU, activation std deviation per layer:")
xavier_x = x.copy()
for i in range(len(layer_sizes) - 1):
    weights = xavier_init(layer_sizes[i], layer_sizes[i + 1], seed=i)
    xavier_x = relu(xavier_x @ weights)
    print(f"  Layer {i + 1}: std = {xavier_x.std():.6f}")

print("\nHe Initialization with ReLU, activation std deviation per layer:")
he_x = x.copy()
for i in range(len(layer_sizes) - 1):
    weights = he_init(layer_sizes[i], layer_sizes[i + 1], seed=i)
    he_x = relu(he_x @ weights)
    print(f"  Layer {i + 1}: std = {he_x.std():.6f}")
